export function toJsonSpawnRuntimeRequest(value: SpawnRuntimeRequest): Json {
    return {
        worldId: toJsonWorldId(value.worldId),
        program: toJsonBlob(value.program),
        ...(value.options === undefined ? {} : { options: toJsonRuntimeOptions(value.options) }),
        ...(value.environment === undefined ? {} : { environment: toJsonEnvironment(value.environment) }),
        conditions: toJsonConditionSet(value.conditions),
    };
}

/** Return one SpawnRuntimeRequest from one JSON value. */
export function fromJsonSpawnRuntimeRequest(value: Json): SpawnRuntimeRequest {
    const object = jsonObject(value);

    return {
        worldId: fromJsonWorldId(jsonField(object, "worldId")),
        program: fromJsonBlob(jsonField(object, "program")),
        options: jsonOptional(object, "options", (value) => fromJsonRuntimeOptions(value)),
        environment: jsonOptional(object, "environment", (value) => fromJsonEnvironment(value)),
        conditions: fromJsonConditionSet(jsonField(object, "conditions")),
    };
}

/** One materialized World topology. */
export type Topology = {
    /** Registered entity definitions. */
    readonly entityDefinitions: ReadonlyArray<EntityDefinition>;
    /** Registered edge definitions. */
    readonly edgeDefinitions: ReadonlyArray<EdgeDefinition>;
    /** Live topology entities. */
    readonly entities: ReadonlyArray<Entity>;
    /** Live topology edges. */
    readonly edges: ReadonlyArray<Edge>;
};

export const Topology = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: Topology): void {
        encodeTopology(writer, value);
    },

    /** Decode one Topology. */
    decode(reader: BinaryReader): Topology {
        return decodeTopology(reader);
    },

    /** Return this value as JSON. */
    toJson(value: Topology): Json {
        return toJsonTopology(value);
    },

    /** Return one Topology from one JSON value. */
    fromJson(value: Json): Topology {
        return fromJsonTopology(value);
    },
};

/** Encode one Topology. */
export function encodeTopology(writer: BinaryWriter, value: Topology): void {
    writer.writeUnsigned(value.entityDefinitions.length);
    for (const item0 of value.entityDefinitions) {
        encodeEntityDefinition(writer, item0);
    }
    writer.writeUnsigned(value.edgeDefinitions.length);
    for (const item1 of value.edgeDefinitions) {
        encodeEdgeDefinition(writer, item1);
    }
    writer.writeUnsigned(value.entities.length);
    for (const item2 of value.entities) {
        encodeEntity(writer, item2);
    }
    writer.writeUnsigned(value.edges.length);
    for (const item3 of value.edges) {
        encodeEdge(writer, item3);
    }
}

/** Decode one Topology. */
export function decodeTopology(reader: BinaryReader): Topology {
    const entityDefinitions = (() => { const length0 = reader.readNumber(); const items0: Array<EntityDefinition> = []; for (let index = 0; index < length0; index += 1) { items0.push(decodeEntityDefinition(reader)); } return items0; })();
    const edgeDefinitions = (() => { const length1 = reader.readNumber(); const items1: Array<EdgeDefinition> = []; for (let index = 0; index < length1; index += 1) { items1.push(decodeEdgeDefinition(reader)); } return items1; })();
    const entities = (() => { const length2 = reader.readNumber(); const items2: Array<Entity> = []; for (let index = 0; index < length2; index += 1) { items2.push(decodeEntity(reader)); } return items2; })();
    const edges = (() => { const length3 = reader.readNumber(); const items3: Array<Edge> = []; for (let index = 0; index < length3; index += 1) { items3.push(decodeEdge(reader)); } return items3; })();

    return {
        entityDefinitions,
        edgeDefinitions,
        entities,
        edges,
    };
}

/** Return one JSON value for one Topology. */
export function toJsonTopology(value: Topology): Json {
    return {
        entityDefinitions: value.entityDefinitions.map((item0) => toJsonEntityDefinition(item0)),
        edgeDefinitions: value.edgeDefinitions.map((item0) => toJsonEdgeDefinition(item0)),
        entities: value.entities.map((item0) => toJsonEntity(item0)),
        edges: value.edges.map((item0) => toJsonEdge(item0)),
    };
}

/** Return one Topology from one JSON value. */
export function fromJsonTopology(value: Json): Topology {
    const object = jsonObject(value);

    return {
        entityDefinitions: jsonArray(jsonField(object, "entityDefinitions")).map((item0) => fromJsonEntityDefinition(item0)),
        edgeDefinitions: jsonArray(jsonField(object, "edgeDefinitions")).map((item0) => fromJsonEdgeDefinition(item0)),
        entities: jsonArray(jsonField(object, "entities")).map((item0) => fromJsonEntity(item0)),
        edges: jsonArray(jsonField(object, "edges")).map((item0) => fromJsonEdge(item0)),
    };
}

/** Request to watch World Observations. */
export type WatchObservationsRequest = {
    /** World to watch. */
    readonly worldId: WorldId;
    /** Observation selection. */
    readonly query: ObservationQuery;
};

export const WatchObservationsRequest = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: WatchObservationsRequest): void {
        encodeWatchObservationsRequest(writer, value);
    },

    /** Decode one WatchObservationsRequest. */
    decode(reader: BinaryReader): WatchObservationsRequest {
        return decodeWatchObservationsRequest(reader);
    },

    /** Return this value as JSON. */
    toJson(value: WatchObservationsRequest): Json {
        return toJsonWatchObservationsRequest(value);
    },

    /** Return one WatchObservationsRequest from one JSON value. */
    fromJson(value: Json): WatchObservationsRequest {
        return fromJsonWatchObservationsRequest(value);
    },
};

/** Encode one WatchObservationsRequest. */
export function encodeWatchObservationsRequest(writer: BinaryWriter, value: WatchObservationsRequest): void {
    encodeWorldId(writer, value.worldId);
    encodeObservationQuery(writer, value.query);
}

/** Decode one WatchObservationsRequest. */
export function decodeWatchObservationsRequest(reader: BinaryReader): WatchObservationsRequest {
    const worldId = decodeWorldId(reader);
    const query = decodeObservationQuery(reader);

    return {
        worldId,
        query,
    };
}

/** Return one JSON value for one WatchObservationsRequest. */
export function toJsonWatchObservationsRequest(value: WatchObservationsRequest): Json {
    return {
        worldId: toJsonWorldId(value.worldId),
        query: toJsonObservationQuery(value.query),
    };
}

/** Return one WatchObservationsRequest from one JSON value. */
export function fromJsonWatchObservationsRequest(value: Json): WatchObservationsRequest {
    const object = jsonObject(value);

    return {
        worldId: fromJsonWorldId(jsonField(object, "worldId")),
        query: fromJsonObservationQuery(jsonField(object, "query")),
    };
}
